insert into public.cms_documents(kind,slug,body) values('page','gomulu-sistemler','{"title":"Gömülü Sistemler","summary":"PCB tasarımı, elektronik donanım ve gömülü yazılım mühendisliği.","paragraphs":["Donanımla yazılımın birlikte düşünüldüğü sistemler.","Gömülü sistem geliştirme; işlem birimi, çevre birimleri, yazılım ve haberleşme arayüzlerinin birlikte ele alınmasını gerektirir. Buradaki başlıklar teknik yaklaşımın genel bir açıklamasıdır.","Konuya ait kavramlar ve çalışma ilkeleri; doğrulanmış proje bilgileri ayrıca yayınlanacaktır.","Elektronik bileşenlerin işlevsel bir sistem içinde düzenlenmesine dair temel yaklaşım.","Donanım kaynaklarını yöneten ve sistem davranışını tanımlayan yazılım katmanı.","Donanım ve yazılımın birlikte değerlendirilmesi, arayüzlerin doğrulanması.","Sistemler birlikte çalışır: Gömülü Sistemler ile Sensör Füzyonu birbirini tamamlayan mühendislik alanlarıdır. Teknoloji başlıkları birbirinden bağımsız değildir."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','haber-detay','{"title":"Tengri AI Paylaşımı","summary":"Tengri AI ve bağlantılı savunma ağları konusunda kamuya açık şirket tanıtımı.","paragraphs":["Yapay zekâ destekli savunma ağı yaklaşımı üzerine şirket paylaşımı.","İstikbal Aerospace, Tengri AI tanıtımında çok katmanlı yapay zekâ, tehdit değerlendirme, hava ve kara sistemleri arasında koordinasyon ve ağ tabanlı karar desteği hedeflerini paylaştı.","Sensör verilerinin bir araya getirilmesi, çoklu hedeflerin değerlendirilmesi ve bilgi paylaşımı, tanıtımda öne çıkan ana başlıklardır. Açıklanan konseptler doğrulanmış operasyonel performans bilgisi olarak sunulmamaktadır.","Orijinal LinkedIn paylaşımı ↗"],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','haberler','{"title":"Haberler & Duyurular","summary":"İstikbal Aerospace Tengri AI ve uçuş kontrolcüsü teknoloji paylaşımları.","paragraphs":["İstikbal Aerospace’in kamuya açık açıklamaları ve teknoloji paylaşımları.","İstikbal Aerospace’in kamuya açık teknoloji tanıtımlarından seçilen içerikler. Paylaşım ve duyurular ayrı kategorilerde izlenebilir.","Şirketin Tengri AI tanıtımında ağ bağlantılı savunma sistemleri ve çok katmanlı yapay zekâ vizyonu anlatılıyor.","Şirketin uçuş kontrol sistemlerine yönelik yapay zekâ ve kontrol algoritmaları odaklı teknoloji paylaşımı.","Bu kategoride yayımlanmış bir içerik bulunmuyor."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','hava-savunma-aglari','{"title":"Hava Savunma Ağları","summary":"Hava savunma ağları, bağlantılı sistemler ve karar destek teknolojileri.","paragraphs":["Algılama, bağlantı ve karar destek yaklaşımı.","İstikbal Aerospace’in kamuya açık açıklamalarında hava savunma ağları ve yapay zekâ destekli koordinasyon yaklaşımları çalışma alanları arasında yer alır.","Havacılık çalışmalarında birbirini tamamlayan temel mühendislik başlıkları.","Farklı veri kaynaklarından durumsal bilgi elde etme yaklaşımı.","Bağlı sistemler arasında haberleşme ve bilgi akışı.","Tengri AI başlığıyla ilişkili değerlendirme ve koordinasyon katmanları.","Otonom sistemler, gömülü donanım ve sensör füzyonu bu mimarilerle ilişkili mühendislik disiplinleridir."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','iha-sistemleri','{"title":"İnsansız Hava Sistemleri","summary":"İnsansız hava platformlarında kontrol, haberleşme ve algılama teknolojilerine genel bakış.","paragraphs":["Hava platformları, otonom uçuş ve sistem mühendisliği.","İnsansız hava araçları; gövde, elektronik, uçuş kontrolü, haberleşme ve sensör sistemlerinin birlikte çalışmasını gerektiren bütünleşik platformlardır.","Havacılık çalışmalarında birbirini tamamlayan temel mühendislik başlıkları.","Uçuş kontrolü ve gömülü sistemler ile platform yönetimi.","Sensör verileri, karar mekanizmaları ve kontrol katmanları.","Verinin platform bileşenleri arasında ve bağlantılı sistemlerde iletilmesi.","Otonom sistemler, gömülü donanım ve sensör füzyonu bu mimarilerle ilişkili mühendislik disiplinleridir."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','ileri-haberlesme','{"title":"İleri Haberleşme","summary":"Bağlantılı platformlarda veri iletimi, haberleşme ve sistem entegrasyonu.","paragraphs":["Bağlantılı sistemler arasında bilgi akışı ve entegrasyon.","İstikbal Aerospace’in kamuya açık şirket özetinde haberleşme sistemleri ve şifreli taktik veri bağlantıları çalışma alanları arasında anılmaktadır. Burada haberleşme mimarilerinin genel ilkeleri yer alır; doğrulanmamış teknik uygulama, kapasite veya operasyonel ürün iddiası sunulmaz.","Konuya ait kavramlar ve çalışma ilkeleri; doğrulanmış proje bilgileri ayrıca yayınlanacaktır.","Bağlantılı platformlar arasında durum ve ölçüm bilgilerinin aktarılmasına dair temel yaklaşım.","İletilen bilginin güvenliğinin ve tutarlılığının sistem tasarımında değerlendirilmesi.","Haberleşme katmanının sensörler, gömülü yazılım ve üst sistemlerle birlikte ele alınması.","Sistemler birlikte çalışır: İleri Haberleşme ile Sensör Füzyonu birbirini tamamlayan mühendislik alanlarıdır. Teknoloji başlıkları birbirinden bağımsız değildir."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','iletisim','{"title":"İletişim","summary":"İstikbal Aerospace kurumsal iletişim bilgileri.","paragraphs":["İstikbal Aerospace ile iletişime geçin.","Genel sorular, kurumsal iş birlikleri ve teknoloji alanları hakkında bilgi için.","İletişim formu henüz sunucuya bağlı değildir. Doğrudan e-posta veya telefon yoluyla ulaşabilirsiniz.","Bu form şu anda mesaj göndermiyor. Göndermek için yukarıdaki doğrudan iletişim bilgilerini kullanın."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','index','{"title":"Ana Sayfa","summary":"İstikbal Aerospace havacılık, otonom sistemler, gömülü elektronik ve mühendislik alanları.","paragraphs":["Havacılık, gömülü elektronik ve otonom sistemlerin kesişiminde mühendislik.","Gömülü elektronik.Otonom hareket.Entegre sistemler.","İnsansız hava platformlarından uçuş elektroniğine, bağlantılı sistem mimarilerinden otonom çözümlere uzanan çalışma alanları.","İnsansız platform mimarileri ve hava aracı sistemleri.","Donanım, yazılım ve kontrol katmanları.","Birbirine bağlı savunma sistemleri yaklaşımı.","Elektronik tasarımdan verinin birleştirilmesine uzanan temel çalışma alanları.","Algılama, karar süreçleri ve kontrol algoritmaları.","Elektronik kart tasarımı, donanım ve gömülü yazılım.","Farklı algılayıcılardan gelen verilerin bütünleştirilmesi.","Ağ tabanlı karar destek ve savunma teknolojileri yaklaşımı.","Hava ve kara sistemlerinin koordinasyonuna yönelik yapay zekâ temelli savunma ağı yaklaşımı. Algılama, tehdit değerlendirme ve karar destek katmanları üzerine çalışmalar.","PCB tasarımı, otonom hareket mühendisliği ve gömülü donanım gibi alanlarda araştırma ve geliştirme yaklaşımı.","Elektronik donanım, gömülü yazılım ve otonom kontrolün birbirini tamamlayan disiplinler olarak ele alındığı mühendislik alanları.","Şirketin paylaştığı teknoloji çalışmalarına ve duyurularına göz atın.","İstikbal Aerospace tarafından kamuya açık olarak tanıtılan Tengri AI''ın odaklandığı teknoloji alanlarını keşfedin.","Antalya merkezli İstikbal Aerospace; havacılık, gömülü elektronik, PCB tasarımı ve otonom sistem mühendisliğini bir araya getiren çalışmalar yürütür."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','kabiliyetler','{"title":"Kabiliyetler","summary":"İstikbal Aerospace''in kamuya açık mühendislik uzmanlık ve teknoloji alanları.","paragraphs":["İnsansız sistemlerden gömülü elektroniğe uzanan mühendislik çalışma alanları.","İstikbal Aerospace’in kamuya açık faaliyet ve uzmanlık tanıtımlarında yer alan başlıklar: insansız hava sistemleri, roket sistemleri, hava savunma ağları, haberleşme, gömülü donanım ve algılama.","Hava platformları ve otonom uçuş mimarileri.","Ağ bağlantılı hava savunma ve karar destek yaklaşımı.","Bağlantılı platformlar ve taktik veri iletimi odağı.","Roket projelerinde uçuş elektroniği ve sistem entegrasyonu hakkında genel mühendislik çerçevesi.","Elektronik kart tasarımı ve donanım-yazılım bütünlüğü.","Birden fazla veri kaynağının birlikte değerlendirilmesi.","Veri analizi, kontrol mantığı ve karar mekanizmalarının bir arada ele alındığı sistemler.","Elektronik kart tasarımı, gömülü işlemciler ve donanım-yazılım entegrasyonu.","Farklı sensör verilerinin işlenmesi ve tek bir sistem görünümüne dönüştürülmesi.","Şirketin yapay zekâ ve ağ merkezli karar desteği üzerine kamuya açık teknoloji yaklaşımı, diğer mühendislik disiplinleriyle ilişkilidir."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','kurumsal','{"title":"Kurumsal","summary":"İstikbal Aerospace mühendislik yaklaşımı, prototipleme ve sistem entegrasyonu.","paragraphs":["Havacılık, gömülü sistemler ve otonom yazılım odağında disiplinler arası mühendislik.","İstikbal Aerospace, Antalya / Kepez merkezli; havacılık, uzay ve savunma teknolojilerine yönelik alt sistemler, gömülü elektronik ve otonom yazılım çalışmalarına odaklanan bir teknoloji ve AR-GE girişimidir.","Elektronik tasarım, gömülü uçuş mimarileri ve otonom algoritmalar birbirinden bağımsız parçalar değildir. İstikbal Aerospace, kamuya açık kurumsal tanıtımında bu disiplinleri birlikte ele alan, çevik ve prototip geliştirmeye odaklı bir mühendislik yaklaşımı benimsediğini ifade eder.","Yaklaşımın odağında, kavramsal tasarımların donanım ve yazılımla buluşturulması; alt sistemlerin birlikte çalışabilir, incelenebilir ve test edilebilir yapılar olarak değerlendirilmesi bulunur.","İstikbal Aerospace’in kamuya açık tanıtımında öne çıkan mühendislik süreçleri.","Elektronik donanım, uçuş mimarileri ve yazılım bileşenlerini ortak bir sistem çerçevesinde değerlendirme.","Kavramsal fikirlerin elektronik tasarım, gömülü yazılım ve algoritma geliştirmeyle somutlaştırılması.","Farklı bileşenler arasında veri akışı, kontrol ve sistem davranışının bütün olarak ele alınması.","Şirketin kamuya açık tanıtımlarında yer alan çalışma başlıklarını ilgili sayfalardan inceleyebilirsiniz.","Hava araçları için donanım ve yazılım mimarilerinin tasarımı.","Algılama, karar mekanizmaları ve otonom sistemlerin mühendislik temelleri.","Tengri AI çevresinde ele alınan yapay zekâ destekli savunma ağı konseptleri.","İstikbal Aerospace’in kamuya açık şirket profilinde merkez konumu Kepez / Antalya olarak belirtilmektedir. İş birliği ve iletişim talepleri için iletişim sayfamıza ulaşabilirsiniz."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','otonom-sistemler','{"title":"Otonom Sistemler","summary":"Algılama, karar mekanizmaları ve kontrol sistemlerine genel bakış.","paragraphs":["Algılama, karar verme ve kontrolün buluştuğu alan.","Otonom sistemler; çevreyi algılama, veriyi yorumlama ve belirlenen hedeflere göre hareket üretme gibi farklı mühendislik disiplinlerini bir araya getirir. Bu sayfa, konunun genel yaklaşımını tanıtır.","Konuya ait kavramlar ve çalışma ilkeleri; doğrulanmış proje bilgileri ayrıca yayınlanacaktır.","Sensörlerden gelen verilerin sistem tarafından yorumlanmasına yönelik mühendislik yaklaşımı.","Algılanan duruma göre kuralların ve algoritmaların rolünü açıklayan genel çerçeve.","Ölçüm, kontrol ve geri bildirim döngülerinin sistem tasarımındaki yeri.","Sistemler birlikte çalışır: Otonom Sistemler ile Gömülü Sistemler birbirini tamamlayan mühendislik alanlarıdır. Teknoloji başlıkları birbirinden bağımsız değildir."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','platform-detay','{"title":"Platform Detayı","summary":"Havacılık platformları, uçuş elektroniği ve sistem entegrasyonunun temelleri.","paragraphs":["Platform mühendisliği, uçuş elektroniği ve sistem entegrasyonu.","İstikbal Aerospace’in gömülü donanım, otonom sistemler ve mühendislik çalışma alanları birlikte ele alınır."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','platformlar','{"title":"Platformlar","summary":"İnsansız hava sistemleri, gömülü uçuş mimarileri ve hava savunma sistemleri çalışma alanları.","paragraphs":["Hava platformları, uçuş kontrolü ve sistem mühendisliği odağındaki çalışma başlıkları.","İstikbal Aerospace’in kamuya açık uzmanlık alanlarından hareketle sunulan sistem aileleri. Bu başlıklar bir ürün kataloğu değil, mühendislik alanlarıdır.","Uçuş kontrolü, algılama ve bağlantılı alt sistemlerin bütünleşik mimarisi.","Uçuş elektroniği, gömülü yazılım ve platform kontrolünün bileşenleri.","Bağlantılı sistemler ve karar destek teknolojileri yaklaşımı.","Şirketin paylaştığı yeni nesil uçuş kontrolcüsü tanıtımında yapay zekâ ile ilişkili kontrol algoritmaları, uçuş güvenliği ve verimlilik hedefleri öne çıkıyor. Teknolojinin mühendislik temellerini inceleyin.","Elektronik tasarım, yazılım ve sensör verisinin birlikte değerlendirilmesi platform mühendisliğinin temelindedir.","Algılama ve kontrolün birleştiği yazılım alanı.","Uçuş elektroniği ve sistem denetimi.","Çoklu veri kaynağının birlikte değerlendirilmesi."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','proje-detay','{"title":"AR-GE Detayı","summary":"Elektronik tasarım, gömülü sistemler ve otonom mühendislik çalışma alanları.","paragraphs":["Elektronik tasarım ve otonom mühendislik çalışmaları.","İstikbal Aerospace’in gömülü donanım, otonom sistemler ve mühendislik çalışma alanları birlikte ele alınır."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','projeler','{"title":"Projeler & AR-GE","summary":"İstikbal Aerospace kamuya açık teknoloji paylaşımları ve AR-GE çalışma alanları.","paragraphs":["Kamuya açık teknoloji tanıtımları ve mühendislik çalışma alanları.","İstikbal Aerospace’in kamuya açık tanıtımlarında yer alan çalışmalar. Geliştirme ve test aşamalarına ilişkin ayrıntılar şirket onayına bağlıdır.","Bağlantılı hava ve kara sistemleri arasında durumsal farkındalık ve karar desteği vizyonu.","Yapay zekâ destekli kontrol algoritmalarını ve uçuş sistemlerini bir araya getirmeyi hedefleyen teknoloji paylaşımı.","Kurumsal faaliyet tanıtımında yer alan çalışma alanları; bunlar tek başına tamamlanmış projeler olarak listelenmemektedir.","Gömülü donanım için elektronik kart mimarileri.","Karar, kontrol ve geri bildirim mekanizmaları.","Sensör bilgisi ve sistem entegrasyonu.","Fikirlerin donanım ve yazılımla buluştuğu sistem geliştirme adımları. PCB tasarımı ve gömülü yazılımın uçuş elektroniğiyle kurduğu ilişki bütünleşik sistem yaklaşımının parçasıdır.","Görev ve sistem gereksinimlerinin belirlenmesi.","Donanım ve arayüzlerin tasarlanması.","Gömülü yazılım ve kontrol algoritmalarının geliştirilmesi.","Alt sistemlerin birlikte değerlendirilmesi."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','roket-sistemleri','{"title":"Roket Sistemleri","summary":"Roket teknolojileriyle ilişkili uçuş elektroniği, telemetri ve sistem mühendisliği.","paragraphs":["Uçuş elektroniği, telemetri ve sistem bütünlüğü.","Roket sistemleri, İstikbal Aerospace’in kamuya açık uzmanlık alanları listesinde geçmektedir. Bu sayfa roket projelerinde ele alınan genel mühendislik disiplinlerini tanıtır; şirkete ait belirli bir ürün, uçuş testi veya performans iddiası içermez.","Konuya ait kavramlar ve çalışma ilkeleri; doğrulanmış proje bilgileri ayrıca yayınlanacaktır.","Algılama, kontrol ve uçuş bilgisinin değerlendirilmesinde elektronik bileşenlerin genel rolü.","Sistem verilerinin izlenmesi ve bağlantılı birimlerle bilgi alışverişi.","Elektronik, yazılım ve mekanik alt sistemlerin bütün halinde ele alınması.","Sistemler birlikte çalışır: Roket Sistemleri ile Gömülü Uçuş Mimarileri birbirini tamamlayan mühendislik alanlarıdır. Teknoloji başlıkları birbirinden bağımsız değildir."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','sensor-fuzyonu','{"title":"Sensör Füzyonu","summary":"Farklı algılayıcılardan gelen verilerin birlikte değerlendirilmesi.","paragraphs":["Birden fazla veri kaynağından daha tutarlı bir tablo.","Sensör füzyonu, farklı algılayıcılardan elde edilen bilgilerin değerlendirilerek birlikte kullanılmasına yönelik mühendislik alanıdır. Açıklamalar genel teknoloji tanıtımıdır; şirkete özgü performans iddiası içermez.","Konuya ait kavramlar ve çalışma ilkeleri; doğrulanmış proje bilgileri ayrıca yayınlanacaktır.","Farklı ölçümlerin nitelikleri, zamanlaması ve kullanılabilirliği.","Farklı kaynaklardan gelen bilgilerin karşılaştırılması ve birlikte ele alınması.","Algılama katmanının otonomi ve gömülü sistemlerle bağlantısı.","Sistemler birlikte çalışır: Sensör Füzyonu ile Otonom Sistemler birbirini tamamlayan mühendislik alanlarıdır. Teknoloji başlıkları birbirinden bağımsız değildir."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','teknolojiler','{"title":"Teknolojiler","summary":"Gömülü sistemler, yapay zekâ, otonomi, sensör füzyonu, roket sistemleri ve haberleşme.","paragraphs":["Donanım, kontrol, algılama ve yapay zekâ tabanlı sistemlerin buluştuğu mühendislik alanları.","Elektronik tasarım, gömülü yazılım, sensör füzyonu ve sistem entegrasyonu birbirini tamamlayan disiplinlerdir. Teknoloji alanları, sistemlerin alt katmanlarını birlikte ele alır.","Sensör verilerinin değerlendirilmesi, karar ve kontrol algoritmaları.","Elektronik kart tasarımı, işlemci tabanlı sistemler ve gömülü yazılım.","Birden fazla algılayıcıdan gelen bilginin birlikte işlenmesi.","Karar destek ve bağlantılı savunma ağlarına odaklanan teknoloji yaklaşımı.","Roket teknolojileriyle ilişkili uçuş elektroniği, telemetri ve sistem mühendisliğine genel bakış.","Bağlantılı platformlarda veri iletimi, güvenli haberleşme ve sistem entegrasyonu.","Tengri AI, şirketin kamuya açık tanıtımında bağlı hava ve kara sistemlerinin koordinasyonunu hedefleyen yapay zekâ yaklaşımı olarak anlatılıyor."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','tengri-ai','{"title":"Tengri AI","summary":"Tengri AI yapay zekâ, durumsal farkındalık ve karar destek teknoloji vizyonu.","paragraphs":["Çok katmanlı yapay zekâ, durumsal farkındalık ve bağlantılı savunma sistemleri vizyonu.","Tengri AI; hava savunma ağları, insansız sistemler, roket teknolojileri ve haberleşme altyapılarının birlikte ele alındığı çok katmanlı bir yapay zekâ ve karar destek vizyonudur.","Tengri AI’ın odağında sensör ve platform verilerinden durumsal farkındalık oluşturulması, tehditlerin değerlendirilmesi ve karar süreçlerinin desteklenmesi yer alır. Amaç, birbirinden ayrı sistemleri daha bütünlüklü bir bilgi ve koordinasyon yapısı içinde değerlendirmektir.","Tasarımın temelinde çoklu kaynak verisi, tahmine dayalı analiz ve bağlantılı sistem mimarileri bulunur.","Tengri AI yaklaşımının temelini oluşturan teknoloji başlıkları.","Farklı kaynaklardan elde edilen bilgilerin ortak bir durum görünümüne katkıda bulunması.","Birden fazla hava unsuruna ilişkin iz bilgilerinin birlikte değerlendirilmesi fikri.","Yapay zekâ destekli değerlendirme ve önceliklendirme süreçlerinin karar desteğindeki rolü.","Gelişen durumların ve olası senaryoların önceden değerlendirilmesine yönelik yaklaşım.","Bağlı unsurlardan alınan bilgilerin ortak bir karar ve koordinasyon çerçevesinde incelenmesi.","Farklı platform ve sistemlerin haberleşme ve veri paylaşımı yoluyla birlikte ele alınması.","Tengri AI’ın kamuya açık vizyonunda farklı sistem ailelerinin ortak bir yapıda değerlendirilmesi hedefleniyor.","Hava araçları ve uçuş sistemlerinin sağladığı verilerin daha geniş bir durum değerlendirmesine dahil edilmesi yaklaşımı.","Hava savunma ve roket sistemleri gibi farklı bileşenler arasında ortak bilgi ve koordinasyon gereksinimi.","Bağlantılı birimler arasında bilgi aktarımı, veri bütünlüğü ve sistemler arası iletişim kavramları.","Kritik altyapılar, stratejik bölgeler ve olası tehdit senaryoları için durumsal farkındalık, önceliklendirme ve öngörüye dayalı değerlendirme bu teknoloji vizyonunun kullanım alanları arasında yer alır. Bunlar mevcut operasyonel yetenek olarak değil, hedeflenen çalışma alanları olarak ele alınmaktadır.","Gömülü yazılım, sensör füzyonu, otonomi ve haberleşme; ağ bağlantılı yapay zekâ yaklaşımlarını tamamlayan mühendislik alanlarıdır."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','ucus-kontrol-paylasimi','{"title":"Uçuş Kontrolcüsü Paylaşımı","summary":"Yapay zekâ ile entegre uçuş kontrolcüsü hakkında kamuya açık teknoloji tanıtımı.","paragraphs":["Yapay zekâ ile entegre yeni nesil uçuş kontrolcüsü tanıtımı.","İstikbal Aerospace’in LinkedIn üzerinden paylaşılan yeni nesil uçuş kontrolcüsü tanıtımında, yapay zekâ destekli kontrol algoritmaları ve uçuş sistemlerinde güvenlik ile verimlilik hedefleri öne çıkarılıyor.","Uçuş elektroniği; gömülü işlem birimleri, sensör verileri, kontrol yazılımı ve geri bildirim mekanizmalarını bir araya getirir. Bu tanıtım, doğrulanmış test sonuçları veya sertifikasyon bilgisi içermediğinden performans değerleri yayımlanmamaktadır.","Şirketin kamuya açık paylaşımı LinkedIn faaliyetinde yer almakta; tam yayın tarihi ve ayrıntılı teknik dokümanları henüz doğrulanmamıştır."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_documents(kind,slug,body) values('page','ucus-mimarileri','{"title":"Gömülü Uçuş Mimarileri","summary":"Uçuş elektroniği, gömülü yazılım ve sistem entegrasyonunun mühendislik temelleri.","paragraphs":["Donanım ve yazılımın birlikte geliştirildiği uçuş sistemleri.","Uçuş sistemlerinde gömülü mimari; kart tasarımı, işlem birimi, çevre birimleri, veri arabirimleri ve kontrol yazılımının birlikte değerlendirilmesini gerektirir.","Havacılık çalışmalarında birbirini tamamlayan temel mühendislik başlıkları.","PCB ve temel elektronik bileşenlerin sistem ihtiyaçlarına göre ele alınması.","Donanım kaynakları, zamanlama ve sistem davranışı.","Bileşenlerin bütünleşik yapı içinde çalışmasının değerlendirilmesi.","Otonom sistemler, gömülü donanım ve sensör füzyonu bu mimarilerle ilişkili mühendislik disiplinleridir."],"date":null,"source":null,"stage":null}'::jsonb) on conflict(kind,slug) do nothing;
insert into public.cms_versions(document_id,revision,body) select id,revision,body from public.cms_documents where kind='page' on conflict do nothing;
